import { useState, useRef } from 'react'
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Snackbar,
  Stack,
  Typography
} from '@mui/material'
import { storageService } from '@/services/storageService'
import { FileDownload as ExportIcon, FileUpload as ImportIcon } from '@mui/icons-material'

/** 导出文件的格式版本，便于将来做兼容 */
const EXPORT_VERSION = 1

interface ExportData {
  _version: number
  _exportedAt: string
  preferences: Record<string, unknown> | null
  timerState: Record<string, unknown> | null
  items: unknown[]
}

interface SettingsPageProps {
  onBack?: () => void
}

export function SettingsPage({ onBack }: SettingsPageProps) {
  const [importConfirmOpen, setImportConfirmOpen] = useState(false)
  const [pendingImportData, setPendingImportData] = useState<ExportData | null>(null)
  const [pendingImportFile, setPendingImportFile] = useState<File | null>(null)
  const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' | 'info' }>({
    open: false,
    message: '',
    severity: 'info'
  })
  const fileInputRef = useRef<HTMLInputElement>(null)

  const showSnackbar = (message: string, severity: 'success' | 'error' | 'info' = 'info') => {
    setSnackbar({ open: true, message, severity })
  }

  const handleCloseSnackbar = () => {
    setSnackbar((prev) => ({ ...prev, open: false }))
  }

  // ==================== 导出 ====================
  const handleExportData = async () => {
    try {
      const allItems = await storageService.getAllItems()

      // 读取用户偏好
      let preferencesData: Record<string, unknown> | null = null
      try {
        const raw = localStorage.getItem('userPreferences')
        if (raw) preferencesData = JSON.parse(raw)
      } catch { /* ignore */ }

      // 读取计时器状态
      let timerData: Record<string, unknown> | null = null
      try {
        const raw = localStorage.getItem('timer-storage')
        if (raw) timerData = JSON.parse(raw)
      } catch { /* ignore */ }

      const exportPayload: ExportData = {
        _version: EXPORT_VERSION,
        _exportedAt: new Date().toISOString(),
        preferences: preferencesData,
        timerState: timerData,
        items: allItems
      }

      const blob = new Blob([JSON.stringify(exportPayload, null, 2)], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `checklist-backup-${new Date().toISOString().slice(0, 10)}.json`
      link.click()
      URL.revokeObjectURL(url)

      showSnackbar(`导出成功！共 ${allItems.length} 条任务数据`, 'success')
    } catch (err) {
      console.error('导出数据失败:', err)
      showSnackbar('导出失败，请重试', 'error')
    }
  }

  // ==================== 导入（解析文件 → 弹确认框） ====================
  const handleImportFileSelect = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file) return

    try {
      const text = await file.text()
      const parsed = JSON.parse(text)

      // 兼容旧格式（纯数组）
      let importData: ExportData
      if (Array.isArray(parsed)) {
        importData = {
          _version: 0,
          _exportedAt: '',
          preferences: null,
          timerState: null,
          items: parsed
        }
      } else if (parsed && typeof parsed === 'object' && Array.isArray(parsed.items)) {
        importData = parsed as ExportData
      } else {
        showSnackbar('文件格式不正确，请选择正确的备份文件', 'error')
        return
      }

      setPendingImportData(importData)
      setPendingImportFile(file)
      setImportConfirmOpen(true)
    } catch (err) {
      console.error('读取文件失败:', err)
      showSnackbar('文件读取失败，请确认文件格式正确', 'error')
    }

    // 重置 input 以便再次选择同一文件
    if (fileInputRef.current) {
      fileInputRef.current.value = ''
    }
  }

  // ==================== 确认导入 ====================
  const handleConfirmImport = async () => {
    if (!pendingImportData) return

    try {
      const data = pendingImportData
      const items = data.items as Record<string, unknown>[]

      // 先清空旧数据，避免重复
      const oldItems = await storageService.getAllItems()
      for (const item of oldItems) {
        await storageService.deleteItem(item.id)
      }

      // 导入任务数据
      let restoredCount = 0
      for (const item of items) {
        // 还原 Date 字段
        if (item.date != null) item.date = new Date(item.date as string | number)
        if (item.createdAt != null) item.createdAt = new Date(item.createdAt as string | number)
        if (item.completedAt) item.completedAt = new Date(item.completedAt as string | number)
        if (item.reviewOccurrenceDate) item.reviewOccurrenceDate = new Date(item.reviewOccurrenceDate as string | number)
        if (item.forgetCurveData && typeof item.forgetCurveData === 'object') {
          const fcd = item.forgetCurveData as Record<string, unknown>
          if (fcd.nextReviewDate) fcd.nextReviewDate = new Date(fcd.nextReviewDate as string | number)
          if (fcd.lastReviewDate) fcd.lastReviewDate = new Date(fcd.lastReviewDate as string | number)
        }
        if (Array.isArray(item.reviewHistory)) {
          item.reviewHistory = (item.reviewHistory as Record<string, unknown>[]).map((entry) => ({
            ...entry,
            occurrenceDate: entry.occurrenceDate ? new Date(entry.occurrenceDate as string | number) : entry.occurrenceDate,
            completedAt: entry.completedAt ? new Date(entry.completedAt as string | number) : entry.completedAt
          }))
        }
        await storageService.saveItem(item as import('@/types').ChecklistItem)
        restoredCount++
      }

      // 导入偏好设置
      if (data.preferences && typeof data.preferences === 'object') {
        localStorage.setItem('userPreferences', JSON.stringify(data.preferences))
      }

      // 导入计时器状态
      if (data.timerState && typeof data.timerState === 'object') {
        localStorage.setItem('timer-storage', JSON.stringify(data.timerState))
      }

      setImportConfirmOpen(false)
      setPendingImportData(null)
      setPendingImportFile(null)

      showSnackbar(`导入成功！已恢复 ${restoredCount} 条任务数据`, 'success')

      // 延迟刷新，让用户看到提示
      setTimeout(() => window.location.reload(), 1500)
    } catch (err) {
      console.error('导入数据失败:', err)
      showSnackbar('导入失败，请重试', 'error')
      setImportConfirmOpen(false)
    }
  }

  const handleCancelImport = () => {
    setImportConfirmOpen(false)
    setPendingImportData(null)
    setPendingImportFile(null)
  }

  return (
    <Box className="settings-page" sx={{ height: '100%', overflowY: 'auto', pr: 1 }}>
      <Box className="settings-page__header" sx={{ mb: 3 }}>
        {/* {onBack && (
          <Button variant="outlined" size="small" sx={{ mb: 2 }} onClick={onBack}>
            返回任务页
          </Button>
        )} */}
        <Typography variant="h4" component="h1" sx={{ mb: 1 }}>
          数据管理
        </Typography>
        <Typography variant="body2" color="text.secondary">
          导出备份与导入恢复。
        </Typography>
      </Box>

      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            导出所有任务和设置到文件，换设备时导入即可恢复数据。
          </Typography>
          <Stack spacing={1.5} sx={{ alignItems: 'center', }}>
            <Button
              variant="outlined"
              size="large"

              startIcon={<ExportIcon />}
              onClick={handleExportData}
              sx={{ width: '30%', fontSize: '1.2rem' }}
            >
              导出数据
            </Button>
            <Button
              variant="outlined"
              size="large"
              startIcon={<ImportIcon />}
              component="label"
              sx={{width: '30%', fontSize: '1.2rem' }}
            >
              导入数据
              <input
                ref={fileInputRef}
                type="file"
                accept=".json"
                hidden
                onChange={handleImportFileSelect}
              />
            </Button>
          </Stack>
        </CardContent>
      </Card>

      {/* 导入确认弹窗 */}
      <Dialog open={importConfirmOpen} onClose={handleCancelImport}>
        <DialogTitle>确认导入数据</DialogTitle>
        <DialogContent>
          <DialogContentText>
            导入将<strong>清空当前所有数据</strong>并替换为备份文件中的内容。
          </DialogContentText>
          {pendingImportData && (
            <Box sx={{ mt: 2, p: 2, bgcolor: 'action.hover', borderRadius: 1 }}>
              <Typography variant="body2">
                📄 文件：{pendingImportFile?.name}
              </Typography>
              <Typography variant="body2">
                📋 任务数量：{pendingImportData.items.length} 条
              </Typography>
              <Typography variant="body2">
                ⚙️ 偏好设置：{pendingImportData.preferences ? '包含' : '不包含'}
              </Typography>
              <Typography variant="body2">
                ⏱️ 计时器状态：{pendingImportData.timerState ? '包含' : '不包含'}
              </Typography>
              {pendingImportData._exportedAt && (
                <Typography variant="body2">
                  🕐 备份时间：{new Date(pendingImportData._exportedAt).toLocaleString('zh-CN')}
                </Typography>
              )}
            </Box>
          )}
          <DialogContentText sx={{ mt: 2 }}>
            此操作不可撤销，确定要继续吗？
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCancelImport}>取消</Button>
          <Button color="primary" variant="contained" onClick={handleConfirmImport}>
            确认导入
          </Button>
        </DialogActions>
      </Dialog>

      {/* 操作反馈提示 */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={4000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  )
}
